/* ---------- Ch 10. Disaster Management ---------- */
window.SSC_MASTERY["sci2:dm"] = {
  one: [
    { q: "Disaster Control Unit helpline number is ___.", model: "The Disaster Control Unit helpline number is 108; Police is 100, Fire is 101 and Ambulance is 102.", keys: ["108", "100", "101", "102"], hot: "Textbook Q" },
    { q: "The Disaster Management Act was passed in ___.", model: "The Disaster Management Act was passed in 2005, defining the authority structure, funds and duties.", keys: ["2005", "authority structure", "funds", "duties"] },
    { q: "Terrorism is which type of disaster?", model: "Terrorism is a man-made disaster, like theft, riot and war, while famine and flood are natural disasters.", keys: ["man-made", "terrorism", "natural"] },
    { q: "Ambulance helpline number is ___.", model: "The ambulance helpline number is 102.", keys: ["102"] },
    { q: "Police helpline number is ___.", model: "The police helpline number is 100, and the fire helpline is 101.", keys: ["100", "101"] }
  ],
  reasons: [
    { q: "Mock drill is useful. Explain why it is said so.", model: "A mock drill gives practice of rescue, evacuation and first aid to students and citizens. This practice removes panic and chaos during a real disaster. The response then becomes fast and organised. Hence mock drill is useful and lives are saved.", keys: ["practice", "rescue", "evacuation", "first aid", "panic", "lives are saved"], hot: "Textbook Q" },
    { q: "Why is it essential to get training of first aid?", model: "Accident victims need primary help before doctors arrive on the spot. Correct first aid relieves their pain at once. It also prevents their condition from deteriorating. Hence training of first aid is essential and it saves lives.", keys: ["primary help", "doctors arrive", "relieves their pain", "condition", "saves lives"] },
    { q: "Effective disaster management makes us well prepared for the future. Explain.", model: "Mapping of danger zones, mock drills, strict rules and public awareness are done in advance. These steps reduce the loss of life and property in the next disaster. Every managed disaster also teaches better planning for the future. Hence effective management keeps us well prepared.", keys: ["mapping", "mock drills", "awareness", "reduce the loss", "planning"] }
  ],
  two: [
    { q: "State the objectives of first aid.", model: "The objectives of first aid are to save the life of the victim. They are to prevent the victim's condition from deteriorating. They are also to relieve pain and attempt to improve the condition.", keys: ["save the life", "prevent", "deteriorating", "relieve pain"] },
    { q: "Which methods are used for transportation of patients? Why do methods differ?", model: "Patients are transported by the cradle method, by carrying on the back, by two hands, or on a stretcher. The method used depends on the type of injury and the condition of the victim.", keys: ["cradle method", "carrying on the back", "stretcher", "injury", "condition"] },
    { q: "Write a short note on mock drill.", model: "A mock drill is a practice demonstration of rescue, evacuation and first aid. It is conducted in schools and communities with student teams. It builds preparedness and removes chaos and fear. Thus everyone responds correctly in a real disaster.", keys: ["practice demonstration", "rescue", "evacuation", "first aid", "schools", "preparedness"] },
    { q: "Write a short note on the Disaster Management Act, 2005.", model: "The Disaster Management Act of 2005 created authorities from the national level down to the district level. It defines the duties of each authority during a disaster. It also provides funds for relief and penalties for violation. Thus it organises the national response.", keys: ["2005", "national", "district", "duties", "funds", "penalties"] },
    { q: "Give reasons for the increase in human-made disasters after World War II.", model: "Population explosion and fast industrialisation increased after the war. Advanced weapons and technology made destruction easier. Terrorism and urban crowding also grew. Hence human-made disasters increased rapidly.", keys: ["population explosion", "industrialisation", "weapons", "technology", "terrorism", "urban crowding"] }
  ],
  three: [
    { q: "Explain the role of the district disaster control unit after a disaster.", model: "The unit starts rapid rescue of trapped people immediately. It sets up relief camps providing food, water and medicines. It coordinates the police, fire-brigade and health departments. It also conducts a damage survey and carries out rehabilitation of victims.", keys: ["rapid rescue", "relief camps", "food", "medicines", "coordinates", "police", "damage survey", "rehabilitation"], hot: "Textbook Q" },
    { q: "Write reasons, effects and remedies for floods.", model: "Floods occur due to heavy rain and sudden release of dam water. Their effects are collapsed bridges, drowned villages and shortage of food. Their remedies are quick rescue, relief shelters, health camps and government compensation.", keys: ["heavy rain", "dam water", "collapsed bridges", "drowned villages", "food", "rescue", "shelters", "health camps", "compensation"] },
    { q: "Write reasons, effects and remedies for earthquakes.", model: "Earthquakes occur due to movements of tectonic plates; Koyna and Latur are sensitive zones. Their effects are collapsed houses and cracks in land. The immediate remedy is drop-cover-hold, followed by assembly on open ground. Later remedies are rescue, relief and rebuilding.", keys: ["tectonic plates", "Koyna", "Latur", "collapsed houses", "cracks", "drop-cover-hold", "open ground", "rescue", "rebuilding"] },
    { q: "Form a disaster-management structure for your school.", model: "The headmaster or a senior teacher acts as the chief of the plan. Student teams are formed for rescue, first aid and communication. Helpline numbers are displayed in every corridor. Regular mock drills are conducted, and an emergency kit is kept ready.", keys: ["headmaster", "chief", "rescue", "first aid", "communication", "helpline numbers", "mock drills", "emergency kit"] },
    { q: "Which aspects of disaster management will you check for your school? Why?", model: "I will check staircase discipline and clear fire exits, because chaos kills more than the disaster in schools. I will check that helpline numbers and the first-aid box are in place. I will also check that mock drills are held, because practice alone creates readiness.", keys: ["staircase discipline", "fire exits", "helpline numbers", "first-aid box", "mock drills", "chaos"] },
    { q: "Explain pre- and post-disaster management for drought.", model: "Pre-disaster management means water conservation through farm ponds and use of drought-resistant crops. Post-disaster management means sending drinking-water tankers to villages. It also means opening fodder camps for animals. Employment schemes and compensation complete the relief.", keys: ["water conservation", "farm ponds", "drought-resistant crops", "drinking-water tankers", "fodder camps", "compensation"] },
    { q: "Identify the disaster type: soil erosion, hepatitis, forest fire, famine, theft.", model: "Soil erosion is a natural disaster caused by water and wind. Hepatitis is a biological or epidemic disaster spreading through infection. A forest fire may be natural or man-made. Famine is a natural disaster of food shortage. Theft is a man-made disaster.", keys: ["soil erosion", "natural", "hepatitis", "biological", "forest fire", "famine", "theft", "man-made"] }
  ],
  five: [
    { q: "Describe disaster management: types, phases and organization.", model: "Disasters are of two types: natural ones like earthquake, flood and drought, and man-made ones like fire, riot and war. Management has three phases. In the pre-disaster phase, mapping and mock drills are done. In the during-disaster phase, rescue and first aid are carried out. In the post-disaster phase, relief and rehabilitation are given. The organisation runs from the national authority to state and district authorities under the 2005 Act.", keys: ["natural", "man-made", "pre-disaster", "mapping", "mock drills", "rescue", "first aid", "relief", "rehabilitation", "national", "district", "2005 Act"] },
    { q: "Explain first aid: objectives, ABC, care in common injuries and transport.", model: "The objectives of first aid are to save life, prevent worsening and relieve pain. The ABC of first aid means checking the airway, breathing and circulation. For bleeding, apply direct pressure; for fracture, tie a splint; for shock, lay the patient flat. Snake-bite needs immobilisation and quick hospital care. Patients are shifted by the cradle method, on the back, or on a stretcher. Hence first-aid training is essential for everyone.", keys: ["save life", "airway", "breathing", "circulation", "bleeding", "pressure", "fracture", "splint", "cradle method", "stretcher", "training"] }
  ]
};

